// Closes the open-ended predecessor when a new version starts, so the two do
// not both claim to be in force on the same day.
func (q *Queries) SupersedePriorVersions(ctx context.Context, arg SupersedePriorVersionsParams) error {
	_, err := q.db.Exec(ctx, supersedePriorVersions, arg.EffectiveFrom, arg.RuleID, arg.NewVersionID)
	return err
}

